namespace docking.widgets.tree;






/**
 * Class for testing {@link GTreeLazyNode}
 */
public class LazyGTestNode : GTreeLazyNode {
	private string name;
	private int depth;

	LazyGTestNode(string name, int depth) {
		this.name = name;
		this.depth = depth;
	}

	/* @Override */
	public string getName() {
		return name;
	}

	/* @Override */
	public Icon getIcon(bool expanded) {
		return null;
	}

	/* @Override */
	public string getToolTip() {
		return "tooltip: " + name;
	}

	/* @Override */
	public bool isLeaf() {
		return depth == 0;
	}

	/* @Override */
	protected List<GTreeNode> generateChildren() {
		List<GTreeNode> list = new();
		if (depth == 0) {
			return list;
		}

		for (int i = 0; i < 3; i++) {
			string childName = name + "_" + i;
			list.add(new LazyGTestNode(childName, depth - 1));
		}
		return list;
	}

}
